function safeString(value){
  let s=String(value??'');
  const esc=v=>String(v).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  for(const z of Array.isArray(x.pii_slovar)?x.pii_slovar:[]){
    const v=z?.znachenie_zashchishchennoe,p=z?.psevdometka;
    if(v!=null&&String(v).length>=2&&p) s=s.replace(new RegExp(esc(v),'gi'),String(p));
  }
  return s.replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,'<EMAIL>')
    .replace(/(?<!\w)(?:\+?\d[\d\s().-]{8,}\d)(?!\w)/g,'<TELEFON>')
    .replace(/(?<!\w)@[A-Za-z0-9_]{5,32}\b/g,'<USERNAME>')
    .replace(/(?<![\p{L}\p{N}_])(меня\s+зовут|мо[её]\s+имя)\s+([А-ЯЁA-Z][А-ЯЁA-Za-zа-яё-]{1,40})/giu,'$1 <PERSON>');
}
function safeValue(v){
  if(typeof v==='string') return safeString(v);
  if(Array.isArray(v)) return v.map(safeValue);
  if(v&&typeof v==='object') return Object.fromEntries(Object.entries(v).map(([k,z])=>[k,safeValue(z)]));
  return v;
}
