const dim=Number(context._nastroyki?.model?.razmernost);
const fail=reason=>[{json:{...context,vektory_gotovy:false,prichina_peredachi:reason,kontrol:{deystvie:'peredat_cheloveku',prichina:reason,uverennost:1,nuzhen_rag:false}}}];
if(api.error) return fail('embedding_error:'+String(api.error?.message||api.error));
if(!Number.isInteger(dim)||dim<=0||!queries.length||queries.length>3) return fail('embedding_bad_profile_or_queries');
if(!Array.isArray(api.data)||api.data.length!==queries.length) return fail('embedding_bad_batch_count');
const indexed=new Map();
for(const row of api.data){
  const i=row?.index;
  if(!Number.isInteger(i)||i<0||i>=queries.length||indexed.has(i)) return fail('embedding_bad_batch_index');
  const e=row?.embedding;
  if(!Array.isArray(e)||e.length!==dim||e.some(v=>typeof v!=='number'||!Number.isFinite(v))) return fail('embedding_bad_vector');
  indexed.set(i,e);
}
const {_context,zapros_modeli,...lean}=context;
if(lean._source){ const {payload_ishodnyy,...source}=lean._source; lean._source=source; }
// No raw input, prompts, previous responses or vectors are copied into every
