    const hit={fragment_id:id,soderzhanie:String(f.soderzhanie||f.content||''),put_razdela:f.put_razdela||'',podobie:similarity};
    if(!best.has(id)||hit.podobie>best.get(id).podobie) best.set(id,hit);
  }
  const evidence=[...best.values()].sort((a,b)=>b.podobie-a.podobie).slice(0,Number(base._nastroyki?.rag?.evidence_max||8));
  $json={...base,required_points:base.plan_poiska?.required_points||[],evidence,rag_ispolzovan:true};
